package com.vandorlabs.neoforge.ramp;

import com.vandorlabs.ramp.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.world.phys.AABB;

/** Immutable, world-free new stationary part geometry; all coordinates are source authored. */
public final class NativeRampGeometry {
 public record Origin(BlockPos position,List<AABB> shapes){public Origin{position=position.immutable();shapes=List.copyOf(shapes);if(shapes.isEmpty()||shapes.size()>256)throw new IllegalArgumentException("Ramp source-shape count");for(var b:shapes)if(!finite(b)||b.minX<0||b.minY<0||b.minZ<0||b.maxX>1||b.maxY>1||b.maxZ>1)throw new IllegalArgumentException("Ramp source shape bounds");}}
 public record Spec(BlockPos cell,Direction facing,int sourceY,int row,int length,int treadPixels,double low,double high,double start,double end,boolean elevator,int travel,boolean extend,boolean fast,int interpolation,boolean verticalLayout,boolean moat,boolean shaped,List<Origin> origins) implements NativeRampBeltGeometry.Profile {public Spec{cell=cell.immutable();origins=List.copyOf(origins);if(!facing.getAxis().isHorizontal()||row< -64||row>128||Math.abs((long)sourceY-cell.getY())>128||length<1||length>128||treadPixels<1||treadPixels>16||travel<0||travel>2||interpolation<0||interpolation>2||!Double.isFinite(low)||!Double.isFinite(high)||low<0||high>1||high<=low||!Double.isFinite(start)||!Double.isFinite(end)||Math.abs(start)>16||Math.abs(end)>16||origins.size()>128)throw new IllegalArgumentException("Ramp part scalars");var unique=new HashSet<BlockPos>();for(var source:origins){if(!unique.add(source.position))throw new IllegalArgumentException("Duplicate Ramp origin");if(Math.abs((long)source.position.getX()-cell.getX())>64||Math.abs((long)source.position.getY()-cell.getY())>64||Math.abs((long)source.position.getZ()-cell.getZ())>64)throw new IllegalArgumentException("Ramp part origin bounds");}}}
 public record Piece(AABB box,Origin origin,int step,double dx,double dy,double dz){}
 public static final class Snapshot {
  private final List<Piece> pieces;private final AABB bounds;private final long retainedBytes;
  private Snapshot(List<Piece> pieces,AABB bounds){this.pieces=List.copyOf(pieces);this.bounds=bounds;long bytes=160L+160L*pieces.size();var origins=Collections.newSetFromMap(new IdentityHashMap<Origin,Boolean>());for(var piece:pieces)if(piece.origin!=null&&origins.add(piece.origin))bytes+=128L+80L*piece.origin.shapes.size();retainedBytes=bytes;}
  public List<Piece> pieces(){return pieces;}public AABB bounds(){return bounds;}public long retainedBytes(){return retainedBytes;}
 }
 private static final int MAX_WORK=131072,MAX_PIECES=8192;
 private static boolean finite(AABB b){return Double.isFinite(b.minX)&&Double.isFinite(b.minY)&&Double.isFinite(b.minZ)&&Double.isFinite(b.maxX)&&Double.isFinite(b.maxY)&&Double.isFinite(b.maxZ)&&b.maxX>b.minX&&b.maxY>b.minY&&b.maxZ>b.minZ;}
 private static RampGeometry.Box box(AABB b){return new RampGeometry.Box(b.minX,b.minY,b.minZ,b.maxX,b.maxY,b.maxZ);}
 private static RampGeometry.Box intersect(RampGeometry.Box a,RampGeometry.Box b){double x=Math.max(a.minX,b.minX),y=Math.max(a.minY,b.minY),z=Math.max(a.minZ,b.minZ),X=Math.min(a.maxX,b.maxX),Y=Math.min(a.maxY,b.maxY),Z=Math.min(a.maxZ,b.maxZ);return X-x>1e-8&&Y-y>1e-8&&Z-z>1e-8?new RampGeometry.Box(x,y,z,X,Y,Z):null;}
 public static Snapshot snapshot(Spec spec,double pose){if(!Double.isFinite(pose)||pose<0||pose>1)throw new IllegalArgumentException("Ramp pose");var direction=RampGeometry.Direction.valueOf(spec.facing.name());int count=spec.elevator?1:ControllerPlatform.treadCount(spec.treadPixels);long work=0;for(var source:spec.origins)work+=(long)source.shapes.size()*count;if(work>MAX_WORK)throw new IllegalArgumentException("Ramp geometry work budget");var pieces=new ArrayList<Piece>();
  if(spec.origins.isEmpty()&&!spec.verticalLayout&&!spec.moat&&spec.travel==RampGeometry.VERTICAL&&!spec.extend){for(var b:RampGeometry.boxesPixels(direction,spec.cell.getY(),spec.sourceY,spec.low,spec.high,spec.row,spec.length,spec.start,spec.end,spec.treadPixels,pose,spec.elevator,spec.fast,spec.interpolation))add(pieces,spec,b,null,-1,0,0,0,false);return finish(pieces);}
  int hinge=spec.cell.getX()*spec.facing.getStepX()+spec.cell.getZ()*spec.facing.getStepZ()-spec.row;
  for(var source:spec.origins){var origin=source.position;int row=origin.getX()*spec.facing.getStepX()+origin.getZ()*spec.facing.getStepZ()-hinge;
   for(var nativeShape:source.shapes){var shape=box(nativeShape);
    if(spec.verticalLayout&&!spec.moat){for(var moved:VerticalRampGeometry.pieces(direction,origin.getX(),origin.getY(),origin.getZ(),shape,spec.sourceY,spec.length,spec.treadPixels,spec.start,spec.end,pose,spec.elevator,spec.travel,spec.extend,spec.fast,spec.interpolation,false,0))add(pieces,spec,moved.box,source,moved.step,moved.dx,moved.dy,moved.dz,true);continue;}
    if(spec.moat){for(var piece:MoatGeometry.pieces(direction,shape,spec.treadPixels)){int step=MoatGeometry.step(direction,piece,spec.treadPixels);var whole=MoatGeometry.transform(direction,spec.sourceY,spec.length,spec.treadPixels,spec.start,spec.end,pose,spec.fast,spec.interpolation,origin.getY(),step,MoatGeometry.world(piece,origin.getX(),origin.getY(),origin.getZ()),MoatGeometry.world(shape,origin.getX(),origin.getY(),origin.getZ()));double[] d=MoatGeometry.point(direction,spec.sourceY,spec.length,spec.treadPixels,spec.start,spec.end,pose,spec.fast,spec.interpolation,origin.getY(),step,0,0,0);add(pieces,spec,whole,source,step,d[0],d[1],d[2],true);}continue;}
    for(int step=0;step<count;step++){var footprint=RampGeometry.footprintPixels(direction,step,spec.elevator?16:spec.treadPixels,shape.minY,shape.maxY);var part=spec.shaped?intersect(shape,footprint):footprint;if(part==null)continue;var moved=RampGeometry.movingTread(direction,origin.getX(),origin.getY(),origin.getZ(),shape.minY,shape.maxY,row,spec.length,spec.start,spec.end,spec.treadPixels,step,pose,pose,spec.elevator,spec.travel,spec.extend,spec.fast,spec.interpolation);if(spec.shaped)moved=new RampGeometry.Box(moved.minX+part.minX-footprint.minX,moved.minY,moved.minZ+part.minZ-footprint.minZ,moved.maxX+part.maxX-footprint.maxX,moved.maxY,moved.maxZ+part.maxZ-footprint.maxZ);double offset=ControllerPlatform.offsetPixels(row,step,spec.length,spec.treadPixels,spec.start,spec.end,pose,spec.elevator,spec.fast,spec.interpolation);int dx=spec.travel==RampGeometry.VERTICAL?0:spec.travel==RampGeometry.LEFT?spec.facing.getCounterClockWise().getStepX():spec.facing.getClockWise().getStepX(),dz=spec.travel==RampGeometry.VERTICAL?0:spec.travel==RampGeometry.LEFT?spec.facing.getCounterClockWise().getStepZ():spec.facing.getClockWise().getStepZ();add(pieces,spec,moved,source,step,dx*offset,spec.travel==RampGeometry.VERTICAL?offset:0,dz*offset,true);}
   }
  }
  if(spec.extend&&!spec.shaped&&!spec.verticalLayout&&!spec.moat)merge(pieces);return finish(pieces);
 }
 private static void add(List<Piece> result,Spec spec,RampGeometry.Box whole,Origin origin,int step,double dx,double dy,double dz,boolean clip){var b=clip?RampGeometry.clip(whole,spec.cell.getX(),spec.cell.getY(),spec.cell.getZ()):whole;if(b==null)return;if(result.size()>=MAX_PIECES)throw new IllegalArgumentException("Ramp part piece budget");var nativeBox=new AABB(b.minX,b.minY,b.minZ,b.maxX,b.maxY,b.maxZ);if(!finite(nativeBox))throw new IllegalArgumentException("Nonfinite Ramp part geometry");result.add(new Piece(nativeBox,origin,step,dx,dy,dz));}
 static Snapshot finish(List<Piece> pieces){var bounds=new AABB(0,0,0,0,0,0);boolean first=true;for(var part:pieces){bounds=first?part.box:bounds.minmax(part.box);first=false;}return new Snapshot(pieces,bounds);}
 private static void merge(List<Piece> pieces){boolean changed;do{changed=false;for(int i=0;i<pieces.size()&&!changed;i++)for(int j=i+1;j<pieces.size();j++){var a=pieces.get(i);var b=pieces.get(j);var x=a.box;var y=b.box;boolean sameY=Math.abs(x.minY-y.minY)<1e-8&&Math.abs(x.maxY-y.maxY)<1e-8,sameX=Math.abs(x.minX-y.minX)<1e-8&&Math.abs(x.maxX-y.maxX)<1e-8,sameZ=Math.abs(x.minZ-y.minZ)<1e-8&&Math.abs(x.maxZ-y.maxZ)<1e-8;if(!(sameY&&sameZ&&x.maxX>=y.minX-1e-8&&y.maxX>=x.minX-1e-8)&&!(sameY&&sameX&&x.maxZ>=y.minZ-1e-8&&y.maxZ>=x.minZ-1e-8))continue;pieces.set(i,new Piece(new AABB(Math.min(x.minX,y.minX),x.minY,Math.min(x.minZ,y.minZ),Math.max(x.maxX,y.maxX),x.maxY,Math.max(x.maxZ,y.maxZ)),a.origin,a.step,a.dx,a.dy,a.dz));pieces.remove(j);changed=true;break;}}while(changed);}
 private NativeRampGeometry(){}
}
